            return setQuotedNullString();

        }



        private Builder setQuotedNullString() {

            final Character quote = quoteCharacter != null ? quoteCharacter : Constants.DOUBLE_QUOTE_CHAR;

            this.quotedNullString = quote + nullString + quote;

