        if (isQuoteCharacterSet()) {

            printWithQuotes(reader, out);

        } else if (isEscapeCharacterSet()) {

            printWithEscapes(reader, out);

        } else if (out instanceof Writer) {

            IOUtils.copyLarge(reader, (Writer) out);

        } else {

            IOUtils.copy(reader, out);

        }

