            }

        } while (reusableToken.type == TOKEN);

        if (!recordList.isEmpty()) {

            recordNumber++;

            result = new CSVRecord(this, recordList.toArray(Constants.EMPTY_STRING_ARRAY), Objects.toString(sb, null), recordNumber, startCharPosition,

