    @Test
    public void testThreadSafety() throws IOException, InterruptedException {
        final CSVPrinter printer = new CSVPrinter(stringWriter, format);
        final int threadCount = 10;
        final int recordsPerThread = 100;
        Thread[] threads = new Thread[threadCount];

        for (int i = 0; i < threadCount; i++) {
            final int threadNum = i;
            threads[i] = new Thread(() -> {
                try {
                    for (int j = 0; j < recordsPerThread; j++) {
                        printer.printRecord("Thread" + threadNum, "Record" + j);
                    }
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            });
        }

        for (Thread t : threads) {
            t.start();
        }

        for (Thread t : threads) {
            t.join();
        }

        printer.close();

        String output = stringWriter.toString();
        String[] lines = output.split("\n");
        // Each thread writes recordsPerThread records, each record ends with newline
        // Plus potential empty line at end
        assertTrue(lines.length >= threadCount * recordsPerThread);
    }

