        try (java.io.ObjectOutputStream oos = new java.io.ObjectOutputStream(bos)) {
            oos.writeObject(obj);
        }
        return bos.toByteArray();
    }

    @SuppressWarnings("unchecked")
    private <T> T deserialize(byte[] data) throws IOException, ClassNotFoundException {
