    }

    @Test
    public void testPutIn() throws IOException {
        CSVParser parser = parseWithHeader(CSV_WITH_HEADER);
        CSVRecord record = getFirstRecord(parser);

        Map<String, String> map = new HashMap<>();
        map.put("existing", "value");
        record.putIn(map);

