    public <M extends Map<String, String>> M putIn(final M map) {

        final Map<String, Integer> headerMap = getHeaderMapRaw();

        if (headerMap == null) {

            return map;

        }

        headerMap.forEach((key, value) -> {

            if (value < values.length) {

                map.put(key, values[value]);

