        CSVParser parser = parseWithHeader(CSV_WITH_HEADER);
        CSVRecord record = getFirstRecord(parser);

        assertEquals("1", record.get(0));
        assertEquals("2", record.get(1));
        assertEquals("3", record.get(2));
        assertEquals(3, record.size());
    }

