    private CSVRecord getRecord(CSVParser parser, int index) throws IOException {
        Iterator<CSVRecord> it = parser.iterator();
        for (int i = 0; i <= index; i++) {
            assertTrue(it.hasNext());
            if (i == index) {
                return it.next();
            }
            it.next();
        }
        return null;
    }

    @Test
